          "css": ".card { position: relative; max-width: 25rem; padding: 1.5rem; border: 1px solid #d9e1eb; border-radius: 14px; }\n.badge { position: absolute; top: .7rem; right: .7rem; padding: .25rem .5rem; background: #eaf1ff; }",
